// Beide sheets expliciet bij naam ophalen, zodat de node-volgorde niet uitmaakt.
function haalOp(naam) {
  try { return $(naam).all().map(i => i.json); } catch (e) { return []; }
}

let facturen = haalOp('Haal facturen op');
let fouten   = haalOp('Haal fouten op');

// Vangnet: directe input gebruiken als de factuur-node niets opleverde.
if (facturen.length === 0) {
  const directeInput = $input.all().map(i => i.json);
  if (directeInput.some(r => r && r.validatieResultaat !== undefined)) {
    facturen = directeInput;
  }
}

// ── Helpers ──────────────────────────────────────────────────────────────────
function num(v) {
  if (v == null || v === '') return 0;
  if (typeof v === 'number') return v;
  let s = String(v).trim();
  if (s.includes(',') && s.includes('.')) s = s.replace(/\./g, '').replace(',', '.');
  else if (s.includes(',')) s = s.replace(',', '.');
  const n = parseFloat(s.replace(/[^0-9.\-]/g, ''));
  return isNaN(n) ? 0 : n;
}
// Google Sheets levert booleans soms als tekst; NL-sheets als WAAR/ONWAAR.
function bool(v) {
  if (v === true) return true;
  if (v == null) return false;
  return ['true', 'waar', 'ja', '1', 'yes'].includes(String(v).trim().toLowerCase());
}
function pct(deel, geheel) { return geheel > 0 ? Math.round((deel / geheel) * 100) : 0; }

// ── Aggregatie over facturen ──────────────────────────────────────────────────
const totaal = facturen.length;
let pass = 0, review = 0, fatal = 0;
let totaalBedrag = 0, totaalBtw = 0, totaalBetaalbaar = 0, totaalRegels = 0;
const leveranciers = new Set();

// Risico-/fraudesignalen (vervangen de oude risicoscore)
let ibanAfwijkingen = 0, nieuweLeveranciers = 0, lageBetrouwbaarheid = 0;

// Technische UBL-kwaliteit
let techPass = 0, techFatal = 0, techFoutenTotaal = 0;

// Dataverrijking
let omgerekendTotaal = 0, geflagdTotaal = 0, nvtTotaal = 0;
let docConfSom = 0, docConfN = 0;
let pctGlSom = 0, pctGlN = 0;

// Leveranciersmatch
let levConfSom = 0, levConfN = 0, uniekGematcht = 0;
const matchMethode = { btw: 0, kvk: 0, iban: 0, naam: 0, geen: 0, overig: 0 };

// Per leverancier (heatmap) + gemiddelde matchbetrouwbaarheid
const perLeverancier = {};

// Facturen die aandacht vragen
const aandachtFacturen = [];

for (const f of facturen) {
  const res = String(f.validatieResultaat || '').toUpperCase();
  if (res === 'PASS') pass++;
  else if (res === 'REVIEW') review++;
  else if (res === 'FATAL') fatal++;

  totaalBedrag     += num(f.totaalbedrag);
  totaalBtw        += num(f.btwbedrag);
  totaalBetaalbaar += num(f.betaalbaarBedrag);
  totaalRegels     += num(f.aantalRegels);

  const lev = f.leveranciernaam || 'Onbekend';
  leveranciers.add(lev);
  if (!perLeverancier[lev]) perLeverancier[lev] = { totaal: 0, afwijkend: 0, confSom: 0, confN: 0 };
  perLeverancier[lev].totaal++;
  if (res === 'REVIEW' || res === 'FATAL') perLeverancier[lev].afwijkend++;

  // Risicosignalen
  const heeftIbanAfw = bool(f.ibanAfwijking);
  const isNieuw      = bool(f.nieuweOnbekendeLeverancier);
  const lageBtr      = bool(f.betrouwbaarheidIsLaag);
  if (heeftIbanAfw) ibanAfwijkingen++;
  if (isNieuw)      nieuweLeveranciers++;
  if (lageBtr)      lageBetrouwbaarheid++;

  // Technische UBL-validatie
  const tech = String(f.technischResultaat || '').toUpperCase();
  if (tech === 'PASS') techPass++;
  else if (tech === 'FATAL') techFatal++;
  techFoutenTotaal += num(f.aantalTechnischeFouten);

  // Dataverrijking
  omgerekendTotaal += num(f.aantalOmgerekend);
  geflagdTotaal    += num(f.aantalGeflagd);
  nvtTotaal        += num(f.aantalNietVanToepassing);

  if (f.documentConfidence != null && f.documentConfidence !== '') { docConfSom += num(f.documentConfidence); docConfN++; }
  if (f.percentageRegelsZonderGl != null && f.percentageRegelsZonderGl !== '') { pctGlSom += num(f.percentageRegelsZonderGl); pctGlN++; }

  // Leveranciersmatch
  if (f.leverancierConfidence != null && f.leverancierConfidence !== '') {
    const lc = num(f.leverancierConfidence);
    levConfSom += lc; levConfN++;
    perLeverancier[lev].confSom += lc; perLeverancier[lev].confN++;
  }
  if (bool(f.leverancierUniekGematcht)) uniekGematcht++;
  const mm = String(f.leverancierMatchMethode || '').toLowerCase();
  if (matchMethode[mm] !== undefined) matchMethode[mm]++;
  else if (mm) matchMethode.overig++;
  else matchMethode.geen++;

  // Aandachtlijst
  const redenen = [];
  if (heeftIbanAfw)     redenen.push('IBAN-afwijking');
  if (isNieuw)          redenen.push('Nieuwe leverancier');
  if (lageBtr)          redenen.push('Lage betrouwbaarheid');
  if (res === 'FATAL')  redenen.push('Geblokkeerd (FATAL)');
  if (tech === 'FATAL') redenen.push('Technische fout');
  if (redenen.length) {
    aandachtFacturen.push({
      factuurnummer:   f.factuurnummer || '-',
      leveranciernaam: lev,
      bedrag:          num(f.totaalbedrag),
      redenen
    });
  }
}

// ── KPI 1: handmatige handelingen ──────────────────────────────────────────────
const handmatigPct = pct(review + fatal, totaal);
const stpPct = 100 - handmatigPct;
const doelHandmatig = 40;
const doelGehaald = handmatigPct <= doelHandmatig;

// ── KPI 4: technische kwaliteit ────────────────────────────────────────────────
const techTotaal = techPass + techFatal;
const techPassPct = pct(techPass, techTotaal);

// ── Gemiddelden ──────────────────────────────────────────────────────────────
const gemDocConfPct  = docConfN > 0 ? Math.round((docConfSom / docConfN) * 100) : 0;
const gemLevConfPct  = levConfN > 0 ? Math.round((levConfSom / levConfN) * 100) : 0;
const gemPctZonderGl = pctGlN  > 0 ? Math.round(pctGlSom / pctGlN) : 0;
const uniekPct       = pct(uniekGematcht, totaal);

// ── KPI 2: heatmap per leverancier ────────────────────────────────────────────
const heatmap = Object.entries(perLeverancier).map(([naam, d]) => ({
  naam,
  totaal: d.totaal,
  afwijkend: d.afwijkend,
  pct: pct(d.afwijkend, d.totaal),
  conf: d.confN > 0 ? Math.round((d.confSom / d.confN) * 100) : null
})).sort((a, b) => b.pct - a.pct).slice(0, 8);

// ── KPI 3: top-5 fouten (met severity) ──────────────────────────────────────────
const foutTeller = {};
let foutenFatal = 0, foutenReview = 0;
for (const fo of fouten) {
  const code = fo.foutcode || 'onbekend';
  const sev  = String(fo.severity || '').toUpperCase();
  if (sev === 'FATAL') foutenFatal++;
  else if (sev === 'REVIEW') foutenReview++;
  if (!foutTeller[code]) foutTeller[code] = { code, aantal: 0, voorbeeld: fo.omschrijving || '', severity: sev || '-' };
  foutTeller[code].aantal++;
}
const topFouten = Object.values(foutTeller).sort((a, b) => b.aantal - a.aantal).slice(0, 5);

// ── Aandachtlijst sorteren (hoogste bedrag eerst), top 10 ──────────────────────
aandachtFacturen.sort((a, b) => b.bedrag - a.bedrag);
const aandacht = aandachtFacturen.slice(0, 10);

// ── Recente facturen ───────────────────────────────────────────────────────────
const recente = facturen.slice(-15).reverse().map(f => ({
  factuurnummer:      f.factuurnummer || '-',
  leveranciernaam:    f.leveranciernaam || '-',
  factuurdatum:       f.factuurdatum || '-',
  totaalbedrag:       num(f.totaalbedrag),
  validatieResultaat: String(f.validatieResultaat || 'onbekend').toUpperCase()
}));

return [{ json: {
  // basis
  aantalFacturen: totaal, aantalRegels: totaalRegels,
  aantalPass: pass, aantalReview: review, aantalFatal: fatal,
  totaalBedrag, totaalBtw, totaalBetaalbaar, aantalLeveranciers: leveranciers.size,
  // KPI 1
  handmatigPct, stpPct, doelHandmatig, doelGehaald,
  // risico
  ibanAfwijkingen, nieuweLeveranciers, lageBetrouwbaarheid,
  // technisch (KPI 4)
  techPass, techFatal, techPassPct, techFoutenTotaal,
  // dataverrijking
  omgerekendTotaal, geflagdTotaal, nvtTotaal, gemDocConfPct, gemPctZonderGl,
  // leveranciersmatch
  gemLevConfPct, uniekPct, uniekGematcht, matchMethode,
  // KPI's en lijsten
  heatmap, topFouten, foutenFatal, foutenReview, aandacht, recenteFacturen: recente
} }];

const s = $input.first().json;
const eur = n => '\u20ac ' + Number(n || 0).toLocaleString('nl-NL', {minimumFractionDigits: 2, maximumFractionDigits: 2});

const statusKleur = { PASS:'background:#e1f5ee;color:#0f6e56;', REVIEW:'background:#faeeda;color:#854f0b;', FATAL:'background:#fcebeb;color:#a32d2d;' };
const statusLabel = { PASS:'Goedgekeurd', REVIEW:'Review', FATAL:'Actie nodig' };

function kpi(label, waarde, kleur) {
  return `<td width="25%" style="padding:6px">
    <table width="100%" cellpadding="0" cellspacing="0" style="background:#f7fafc;border-radius:8px">
      <tr><td style="padding:12px;text-align:center">
        <div style="font-size:10px;color:#718096;text-transform:uppercase;letter-spacing:0.5px">${label}</div>
        <div style="font-size:20px;font-weight:700;color:${kleur||'#1a202c'};margin-top:4px">${waarde}</div>
      </td></tr></table></td>`;
}

// Risicokaart: groen bij 0, rood bij signalen
function riskCard(label, waarde, sub) {
  const alarm = Number(waarde) > 0;
  const bg = alarm ? '#fcebeb' : '#e1f5ee';
  const fg = alarm ? '#a32d2d' : '#0f6e56';
  return `<td width="25%" style="padding:6px">
    <table width="100%" cellpadding="0" cellspacing="0" style="background:${bg};border-radius:8px">
      <tr><td style="padding:12px;text-align:center">
        <div style="font-size:10px;color:${fg};text-transform:uppercase;letter-spacing:0.5px">${label}</div>
        <div style="font-size:22px;font-weight:700;color:${fg};margin-top:4px">${waarde}</div>
        <div style="font-size:10px;color:${fg};margin-top:2px">${sub||''}</div>
      </td></tr></table></td>`;
}

// Mail-veilige voortgangsbalk
function balk(pctWaarde, kleur, label) {
  const p = Math.max(0, Math.min(100, Number(pctWaarde)||0));
  return `<table width="100%" cellpadding="0" cellspacing="0" style="margin-top:6px">
    <tr><td style="background:#e2e8f0;border-radius:99px;height:24px">
      <table cellpadding="0" cellspacing="0" style="width:${p}%;min-width:40px"><tr>
        <td style="background:${kleur};border-radius:99px;height:24px;text-align:center;color:white;font-weight:700;font-size:12px">${p}%</td>
      </tr></table>
    </td></tr></table>
    ${label ? `<div style="font-size:12px;color:#718096;margin-top:6px">${label}</div>` : ''}`;
}

function heatKleur(p){ if(p===0)return 'background:#e1f5ee;color:#0f6e56';if(p<=25)return 'background:#fef3c7;color:#854f0b';if(p<=50)return 'background:#fed7aa;color:#9a3412';return 'background:#fca5a5;color:#7f1d1d'; }
function sevKleur(x){ if(x==='FATAL')return 'background:#fcebeb;color:#a32d2d';if(x==='REVIEW')return 'background:#faeeda;color:#854f0b';return 'background:#edf2f7;color:#4a5568'; }

// KPI 1 balk
const balkKleur = s.doelGehaald ? '#0f6e56' : (s.handmatigPct <= 60 ? '#854f0b' : '#a32d2d');
const gaugeBalk = balk(s.handmatigPct, balkKleur, `${s.stpPct}% automatisch &middot; doel max 40% handmatig &middot; ${s.doelGehaald?'doel gehaald':'doel nog niet gehaald'}`);

// KPI 4 balk (technische UBL-kwaliteit)
const techBalk = balk(s.techPassPct, s.techPassPct >= 95 ? '#0f6e56' : (s.techPassPct >= 80 ? '#854f0b' : '#a32d2d'),
  `${s.techPass} van ${s.techPass + s.techFatal} facturen technisch valide &middot; ${s.techFoutenTotaal} technische fouten totaal`);

// Heatmap rijen (incl. gemiddelde matchbetrouwbaarheid)
const heatRijen = s.heatmap.length ? s.heatmap.map(h=>`<tr>
  <td style="padding:7px;border-bottom:1px solid #edf2f7;font-size:13px">${h.naam}</td>
  <td style="padding:7px;border-bottom:1px solid #edf2f7;text-align:center;font-size:13px">${h.totaal}</td>
  <td style="padding:7px;border-bottom:1px solid #edf2f7;text-align:center;font-size:13px">${h.afwijkend}</td>
  <td style="padding:7px;border-bottom:1px solid #edf2f7;text-align:center"><span style="${heatKleur(h.pct)};padding:2px 10px;border-radius:6px;font-size:12px;font-weight:600">${h.pct}%</span></td>
  <td style="padding:7px;border-bottom:1px solid #edf2f7;text-align:center;font-size:13px;color:#718096">${h.conf==null?'-':h.conf+'%'}</td>
</tr>`).join('') : '<tr><td colspan="5" style="padding:10px;text-align:center;color:#a0aec0;font-size:13px">Geen leveranciers gevonden</td></tr>';

// Top-fouten rijen (met severity)
const foutRijen = s.topFouten.length
  ? s.topFouten.map(f=>`<tr>
      <td style="padding:7px;border-bottom:1px solid #edf2f7;font-family:monospace;font-size:13px">${f.code}</td>
      <td style="padding:7px;border-bottom:1px solid #edf2f7;text-align:center"><span style="${sevKleur(f.severity)};padding:2px 8px;border-radius:6px;font-size:11px;font-weight:600">${f.severity}</span></td>
      <td style="padding:7px;border-bottom:1px solid #edf2f7;font-size:13px">${f.voorbeeld}</td>
      <td style="padding:7px;border-bottom:1px solid #edf2f7;text-align:center;font-weight:600;font-size:13px">${f.aantal}</td>
    </tr>`).join('')
  : '<tr><td colspan="4" style="padding:10px;text-align:center;color:#a0aec0;font-size:13px">Nog geen fouten geregistreerd</td></tr>';

// Aandachtlijst rijen
const aandachtRijen = s.aandacht.length
  ? s.aandacht.map(a=>`<tr>
      <td style="padding:7px;border-bottom:1px solid #edf2f7;font-family:monospace;font-size:13px">${a.factuurnummer}</td>
      <td style="padding:7px;border-bottom:1px solid #edf2f7;font-size:13px">${a.leveranciernaam}</td>
      <td style="padding:7px;border-bottom:1px solid #edf2f7;text-align:right;font-size:13px">${eur(a.bedrag)}</td>
      <td style="padding:7px;border-bottom:1px solid #edf2f7;font-size:12px">${a.redenen.map(r=>`<span style="background:#fcebeb;color:#a32d2d;padding:1px 7px;border-radius:6px;margin-right:3px;white-space:nowrap">${r}</span>`).join(' ')}</td>
    </tr>`).join('')
  : '<tr><td colspan="4" style="padding:10px;text-align:center;color:#0f6e56;font-size:13px">Geen facturen met risicosignalen</td></tr>';

// Recente facturen
const rijen = s.recenteFacturen.map(f=>{
  const k=statusKleur[f.validatieResultaat]||'background:#f1efe8;color:#5f5e5a;';
  const l=statusLabel[f.validatieResultaat]||f.validatieResultaat;
  return `<tr>
    <td style="padding:8px;border-bottom:1px solid #edf2f7;font-family:monospace;font-size:13px">${f.factuurnummer}</td>
    <td style="padding:8px;border-bottom:1px solid #edf2f7;font-size:13px">${f.leveranciernaam}</td>
    <td style="padding:8px;border-bottom:1px solid #edf2f7;font-size:13px">${f.factuurdatum}</td>
    <td style="padding:8px;border-bottom:1px solid #edf2f7;text-align:right;font-size:13px">${eur(f.totaalbedrag)}</td>
    <td style="padding:8px;border-bottom:1px solid #edf2f7"><span style="${k}padding:2px 10px;border-radius:99px;font-size:12px;font-weight:500">${l}</span></td>
  </tr>`;
}).join('');

// Matchmethode-samenvatting
const mm = s.matchMethode || {};
const matchSamenvatting = `BTW ${mm.btw||0} &middot; KvK ${mm.kvk||0} &middot; IBAN ${mm.iban||0} &middot; Naam ${mm.naam||0} &middot; Geen ${mm.geen||0}`;

const html = `<table width="100%" cellpadding="0" cellspacing="0" style="font-family:Arial,sans-serif;background:#f5f7fa;padding:20px">
<tr><td align="center">
<table width="720" cellpadding="0" cellspacing="0" style="background:white;border-radius:12px;overflow:hidden">
  <tr><td style="background:#1e3c72;padding:24px 28px">
    <div style="color:white;font-size:22px;font-weight:700">Bajo Bouw Control Tower</div>
    <div style="color:#cbd5e0;font-size:14px;margin-top:4px">Inkoopfacturatie &middot; overzicht verwerkte facturen</div>
  </td></tr>

  <tr><td style="padding:16px 22px 4px">
    <table width="100%" cellpadding="0" cellspacing="0"><tr>
      ${kpi('Facturen', s.aantalFacturen, '#1a202c')}
      ${kpi('Factuurregels', s.aantalRegels, '#1a202c')}
      ${kpi('Leveranciers', s.aantalLeveranciers, '#1a202c')}
      ${kpi('Totaal incl. BTW', eur(s.totaalBedrag), '#1a202c')}
    </tr></table>
  </td></tr>

  <tr><td style="padding:4px 22px 8px">
    <table width="100%" cellpadding="0" cellspacing="0"><tr>
      ${kpi('Goedgekeurd', s.aantalPass, '#0f6e56')}
      ${kpi('Review', s.aantalReview, '#854f0b')}
      ${kpi('Actie nodig', s.aantalFatal, '#a32d2d')}
      ${kpi('BTW-bedrag', eur(s.totaalBtw), '#1a202c')}
    </tr></table>
  </td></tr>

  <tr><td style="padding:10px 28px 4px">
    <div style="font-size:15px;font-weight:600;color:#1a202c;margin-bottom:6px">Risicosignalen &middot; betaal- en fraudecontrole</div>
  </td></tr>
  <tr><td style="padding:0 22px 8px">
    <table width="100%" cellpadding="0" cellspacing="0"><tr>
      ${riskCard('IBAN-afwijking', s.ibanAfwijkingen, 'verifieer rekening')}
      ${riskCard('Nieuwe leverancier', s.nieuweLeveranciers, 'niet in stamdata')}
      ${riskCard('Lage betrouwbaarheid', s.lageBetrouwbaarheid, 'AI-confidence laag')}
      ${riskCard('Technische fouten', s.techFatal, 'UBL-validatie')}
    </tr></table>
  </td></tr>

  <tr><td style="padding:12px 28px 4px">
    <div style="font-size:15px;font-weight:600;color:#1a202c;margin-bottom:6px">KPI 1 &middot; Reductie handmatige handelingen</div>
    ${gaugeBalk}
  </td></tr>

  <tr><td style="padding:12px 28px 4px">
    <div style="font-size:15px;font-weight:600;color:#1a202c;margin-bottom:6px">KPI 4 &middot; Technische factuurkwaliteit (UBL)</div>
    ${techBalk}
  </td></tr>

  <tr><td style="padding:12px 22px 4px">
    <table width="100%" cellpadding="0" cellspacing="0"><tr>
      ${kpi('Gem. OCR-betrouwbaarheid', s.gemDocConfPct + '%', '#1a202c')}
      ${kpi('Gem. leveranciersmatch', s.gemLevConfPct + '%', '#1a202c')}
      ${kpi('Uniek gematcht', s.uniekPct + '%', '#1a202c')}
      ${kpi('Regels zonder GL', s.gemPctZonderGl + '%', '#1a202c')}
    </tr></table>
  </td></tr>

  <tr><td style="padding:4px 22px 4px">
    <table width="100%" cellpadding="0" cellspacing="0"><tr>
      ${kpi('Eenheden omgerekend', s.omgerekendTotaal, '#0f6e56')}
      ${kpi('Regels ter review', s.geflagdTotaal, '#854f0b')}
      ${kpi('Geen omrekening', s.nvtTotaal, '#1a202c')}
      ${kpi('Betaalbaar totaal', eur(s.totaalBetaalbaar), '#1a202c')}
    </tr></table>
    <div style="font-size:12px;color:#718096;margin-top:4px;text-align:right">Leveranciersmatch: ${matchSamenvatting}</div>
  </td></tr>

  <tr><td style="padding:16px 28px 8px">
    <div style="font-size:15px;font-weight:600;color:#1a202c;margin-bottom:6px">KPI 2 &middot; Factuurkwaliteit per leverancier</div>
    <div style="font-size:12px;color:#718096;margin-bottom:8px">Percentage facturen met review of blokkade, plus gemiddelde matchbetrouwbaarheid. Benadering op factuurniveau.</div>
    <table width="100%" cellpadding="0" cellspacing="0">
      <tr><th style="text-align:left;padding:7px;border-bottom:2px solid #e2e8f0;font-size:11px;color:#718096;text-transform:uppercase">Leverancier</th>
          <th style="text-align:center;padding:7px;border-bottom:2px solid #e2e8f0;font-size:11px;color:#718096;text-transform:uppercase">Fact.</th>
          <th style="text-align:center;padding:7px;border-bottom:2px solid #e2e8f0;font-size:11px;color:#718096;text-transform:uppercase">Afw.</th>
          <th style="text-align:center;padding:7px;border-bottom:2px solid #e2e8f0;font-size:11px;color:#718096;text-transform:uppercase">%</th>
          <th style="text-align:center;padding:7px;border-bottom:2px solid #e2e8f0;font-size:11px;color:#718096;text-transform:uppercase">Match</th></tr>
      ${heatRijen}
    </table>
  </td></tr>

  <tr><td style="padding:16px 28px 8px">
    <div style="font-size:15px;font-weight:600;color:#1a202c;margin-bottom:6px">KPI 3 &middot; Meest voorkomende fouten</div>
